<template>
  <section class="flex flex-col gap-10">
    <h1 class="font-semibold text-2xl sm:text-3xl">Valid Signature</h1>
    <AppLoader v-if="isLoading" subject="signature details" />
    <AppError v-else-if="error" title="Failed to load signature details" :error="error" />
    <AppEmpty v-else-if="!data" subject="signature details" />
    <Card v-else>
      <CardContent class="flex flex-col gap-4">
        <div class="flex flex-wrap justify-between gap-4 w-full">
          <h3 class="text-xl font-medium">{{ voter_info?.first_name }} {{ voter_info?.last_name }}</h3>
          <div class="flex flex-wrap gap-4">
            <ValidSignatureStatuses
              :collected="data.is_collected"
              :handwriting="data.handwriting_state ? data.handwriting_state : 'na'"
              :voice-verification="data.voice_verification_result"
            />
          </div>
        </div>
        <Separator />
        <SignatureDetailsMain :data="data" />
        <Separator />
        <SignaturePreview
          :image-url="data.ballot_row_url"
          :ballot-page-id="data.ballot_page_id"
          :signature-id="null"
          button-label="Open Petition Page"
        />
        <Separator />
        <h3 class="text-xl font-medium">Voter Information</h3>
        <div v-if="voter_info" class="grid grid-cols-1 md:grid-cols-2 gap-6">
          <LabeledValue
            v-for="(value, key) in voter_info"
            :key="key"
            :label="snakeCaseToCapitalizedCase(key)"
            :value="value"
          />
        </div>
        <AppEmpty v-else variant="table" subject="voter information" />
        <Separator />
        <h3 class="text-xl font-medium">Submitted Signatures</h3>
        <template v-if="data.submitted_signatures.length > 0">
          <NuxtLink
            v-for="item in data.submitted_signatures"
            :key="item.id"
            :to="{ name: 'verification-ballots-signatures-submitted-id', params: { id: item.id } }"
          >
            <BallotsSignaturesListItem :item="item" />
          </NuxtLink>
        </template>
        <AppEmpty v-else subject="submitted signature" variant="table" />
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { getValidSignatureDetails } from '~/client';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'signature',
});

const route = useRoute('verification-ballots-signatures-submitted-id');

const { data, isLoading, error } = useQuery({
  key: () => ['verification.ballot.submitted-signature', route.params.id],
  query: () => getValidSignatureDetails({ composable: '$fetch', path: { valid_signature_id: route.params.id } }),
  enabled: () => !!route.params.id,
});

const voter_info = computed(() => data.value?.voter_info || null);
</script>
